const output = resolve(root, '..', 'public-export');
const scratch = await mkdtemp(resolve(tmpdir(), 'lineguard-release-'));
const members = ['src/index.js', 'src/config.js', 'package.json', 'README.md', 'LICENSE'];
try {
  for (const path of members) {
    const destination = resolve(scratch, 'package', path);
    await mkdir(dirname(destination), { recursive: true });
    await copyFile(resolve(root, path), destination);
  }
  await mkdir(output, { recursive: true });
  const filename = `lineguard-${pkg.version}.tgz`;
  run('tar', ['-czf', resolve(output, filename), '-C', scratch, 'package']);
  const bytes = await readFile(resolve(output, filename));
  const digest = createHash('sha256').update(bytes).digest('hex');
  await writeFile(resolve(output, 'SHA256SUMS'), `${digest}  ${filename}\n`);
  console.log(`Staged ${filename} and SHA256SUMS in ${output}`);
} finally {
  await rm(scratch, { recursive: true, force: true });
}

